// Générer les créneaux automatiquement
const data = $input.first().json;
const offres = data.offres || [];
const rhId = data.rh_id;

const creneaux = [];

// Date de début : prochain lundi à 9h00
const now = new Date();
const dayOfWeek = now.getDay();
const daysUntilMonday = dayOfWeek === 0 ? 1 : (8 - dayOfWeek) % 7 || 7;
now.setDate(now.getDate() + daysUntilMonday);
now.setHours(9, 0, 0, 0);

let currentSlot = new Date(now);
const DUREE = 30; // minutes
const PAUSE = 15; // pause entre entretiens

for (const offre of offres) {
  for (const candidat of offre.candidats) {
    creneaux.push({
      resultat_id: candidat.resultat_id,
      offre_id: offre.offre_id,
      candidat_email: candidat.email,
      candidat_nom: `${candidat.prenom} ${candidat.nom}`,
      date_entretien: currentSlot.toISOString(),
      duree_minutes: DUREE,
      type_entretien: 'presentiel',
      lieu: 'RANDA — ZI BIR EL KASAA BEN AROUS, BEN AROUS'
    });

    currentSlot = new Date(currentSlot.getTime() + (DUREE + PAUSE) * 60000);

    // Pause déjeuner 12h → 14h
    if (currentSlot.getHours() >= 12 && currentSlot.getHours() < 14) {
      currentSlot.setHours(14, 0, 0, 0);
    }

    // Fin de journée 18h → lendemain 9h
    if (currentSlot.getHours() >= 18) {
      currentSlot.setDate(currentSlot.getDate() + 1);
      currentSlot.setHours(9, 0, 0, 0);
      if (currentSlot.getDay() === 6) currentSlot.setDate(currentSlot.getDate() + 2);
      if (currentSlot.getDay() === 0) currentSlot.setDate(currentSlot.getDate() + 1);
    }
  }
}

return [{
  json: {
    n8n_execution_id: $execution.id,
    rh_id: rhId,
    creneaux: creneaux,
    total: creneaux.length
  }
}];
